void PSVECNormalize(const Vec* vec1, Vec* dst)
{
    const f32 xx = vec1->x * vec1->x;
    const f32 yy = vec1->y * vec1->y;
    const f32 xx_zz = PF_SlippiMulAddF32(vec1->z, vec1->z, xx);
    const f32 sqsum = xx_zz + yy;
    const double estimate = PF_GekkoFrsqrte((double) sqsum);
    f32 nwork0 = PF_SlippiMulF32FromF64(estimate, estimate);
    const f32 nwork1 = PF_SlippiMulF32FromF64(estimate, 0.5);
    f32 rsqrt;
    nwork0 = PF_SlippiMulAddF32(-nwork0, sqsum, 3.0F);
    rsqrt = nwork0 * nwork1;
    dst->x = vec1->x * rsqrt;
    dst->y = vec1->y * rsqrt;
    dst->z = vec1->z * rsqrt;
}

